import{_ as l,o as i,c as r,a3 as o}from"./chunks/framework.BsQeBrPm.js";const c=JSON.parse('{"title":"DLC02・競馬場","description":"Anno 117 DLC02「競馬場（The Hippodrome）」の攻略ガイド。戦車競走モニュメント・レースの育成要素・輝きボーナス・無料アップデート2.0を解説。","frontmatter":{"title":"DLC02・競馬場","description":"Anno 117 DLC02「競馬場（The Hippodrome）」の攻略ガイド。戦車競走モニュメント・レースの育成要素・輝きボーナス・無料アップデート2.0を解説。"},"headers":[],"relativePath":"guide/dlc02-hippodrome.md","filePath":"guide/dlc02-hippodrome.md"}'),a={name:"guide/dlc02-hippodrome.md"};function d(e,t,n,s,h,u){return i(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="dlc02・競馬場" tabindex="-1">DLC02・競馬場 <a class="header-anchor" href="#dlc02・競馬場" aria-label="Permalink to &quot;DLC02・競馬場&quot;">​</a></h1><blockquote><p>出典: Anno Union 公式デブログ・Ubisoft News・実機確認。一部の数値は<strong>要検証</strong>。</p></blockquote><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><ul><li>ローマの<strong>戦車競走</strong>（チャリオットレース）をテーマにした2つ目のDLC。</li><li>巨大モニュメント「競馬場」を段階建設し、住民向けのレースイベントを開催できる。</li><li>レースには手持ちの<strong>専門家（スペシャリスト）</strong>を騎手として出走させる。走らせるほど騎手の能力が育つ。</li><li>レースで貯まる<strong>輝き</strong>でモニュメントのレベルと島全体へのボーナスが強化される。</li><li>同時配信の無料アップデート2.0で、名誉ある来賓・英雄級スペシャリスト・フォトモード等が全プレイヤーに追加。</li></ul><h2 id="競馬場モニュメント" tabindex="-1">競馬場モニュメント <a class="header-anchor" href="#競馬場モニュメント" aria-label="Permalink to &quot;競馬場モニュメント&quot;">​</a></h2><ul><li><strong>設置面積</strong>: 敷地は約60×28タイルで、円形闘技場（約28×28タイル）の約2倍の広さを要する。</li><li><strong>建設段階</strong>: 基礎 → 外壁・観客席 → 装飾・VIP用貴賓席の順に段階施工する（各フェーズの必要材料は下記「<a href="#競馬場の建築工程">競馬場の建築工程</a>」を参照）。</li><li><strong>需要充足</strong>: パトリキの「驚異」需要カテゴリーに属し、島全体のパトリキの当該需要を満たす。</li><li>観客はエクィテス・パトリキ（貴賓席）から平民（一般席）まで全階層が楽しむ。</li></ul><h2 id="競馬場の建築工程" tabindex="-1">競馬場の建築工程 <a class="header-anchor" href="#競馬場の建築工程" aria-label="Permalink to &quot;競馬場の建築工程&quot;">​</a></h2><ol><li>新スキルツリー「競馬場」が追加される。まず競馬場スキルを解放する。</li><li>競馬場を設置する。円形闘技場と同様、資材搬入のため倉庫を近隣に置くことを推奨。</li><li>建設フェーズを順に進める。フェーズごとに必要材料と必要労働力が異なる。</li></ol><table tabindex="0"><thead><tr><th>フェーズ</th><th>必要材料</th><th>必要労働力</th></tr></thead><tbody><tr><td>1</td><td>設置のみ</td><td>—</td></tr><tr><td>2</td><td>木材 180／縄 150／瓦 150／布 120</td><td>リベルトゥス 600人</td></tr><tr><td>3</td><td>木材 160／瓦 160／コンクリート 200／鉄 120／<strong>花崗岩</strong> 160</td><td>プレブス 500人</td></tr><tr><td>4</td><td>瓦 300／コンクリート 250／鉄 200／<strong>花崗岩</strong> 200／大理石 300／モザイク 300</td><td>エクィテス 400人</td></tr><tr><td>5</td><td>コンクリート 180／大理石 240／モザイク 120／<strong>青銅</strong> 240／クッション 300／装飾木材 300</td><td>パトリキ 300人</td></tr></tbody></table><ul><li>花崗岩・青銅などのアルビオン（ケルト）産の製品が必要になるため、事前に調達しておくとよい。</li></ul><h2 id="チャリオットレース" tabindex="-1">チャリオットレース <a class="header-anchor" href="#チャリオットレース" aria-label="Permalink to &quot;チャリオットレース&quot;">​</a></h2><ul><li>出走させる騎手（スペシャリスト）は次の4能力を持つ。 <ul><li>速度</li><li>スタミナ</li><li>ダッシュ</li><li>信頼性</li></ul></li><li>レース中は<strong>ダッシュ</strong>を発動して一時的に加速できる。</li><li>レース種別は3種。輝きレベルを上げると上位種別が解放される。</li></ul><table tabindex="0"><thead><tr><th>種別</th><th>出走数</th><th>解放条件</th></tr></thead><tbody><tr><td>アマチュア</td><td>4</td><td>初期から</td></tr><tr><td>クラシック・クアドリガ</td><td>6</td><td>輝きレベルの上昇</td></tr><tr><td>インペリアル</td><td>8</td><td>輝きレベルの上昇</td></tr></tbody></table><ul><li>大きなレースほど得られる輝きは多いが、必要な準備物資・対戦相手の強さも増す。</li><li><strong>騎手の育成</strong>: 出走を重ねると能力が伸びる。ただし騎手ごとに上限値と得意分野が異なる。</li></ul><h2 id="輝きボーナス" tabindex="-1">輝きボーナス <a class="header-anchor" href="#輝きボーナス" aria-label="Permalink to &quot;輝きボーナス&quot;">​</a></h2><ul><li>獲得量はレース種別・供給した準備物資・着順で決まる。</li><li>貯めた輝きでモニュメントのレベルと新レース種別が解放される。</li><li>レベルが上がると島全体に次の効果が生じる: <ul><li>周辺の生産力が上昇する。</li><li>騎兵の攻撃・防御が強化される（+1 攻撃 / +2 防御）。</li><li>リベルトゥスの需要に<strong>パン</strong>が追加される（気づかないうちにパン需要が急増するため要注意）。</li><li>上流階級（エクィテス／パトリキ）の需要に<strong>馬</strong>が追加され、馬ブリーダーが副産物として<strong>戦車</strong>を産出するようになる。</li></ul></li></ul><h2 id="新規リサーチ・アイテム" tabindex="-1">新規リサーチ・アイテム <a class="header-anchor" href="#新規リサーチ・アイテム" aria-label="Permalink to &quot;新規リサーチ・アイテム&quot;">​</a></h2><ul><li>騎手育成に関わる新しいリサーチ技術が追加。</li><li>関連アイテムはクエスト報酬・ウァレリアとの交易・反復リサーチで入手できる。</li></ul><h2 id="無料アップデート2-0-dlc不要" tabindex="-1">無料アップデート2.0（DLC不要） <a class="header-anchor" href="#無料アップデート2-0-dlc不要" aria-label="Permalink to &quot;無料アップデート2.0（DLC不要）&quot;">​</a></h2><ul><li><strong>名誉ある来賓</strong>: 各地から来賓が訪れ、新スペシャリストなどをもたらす。出現率は<strong>名声（Prestige）</strong>と輝きのレベルに依存。</li><li><strong>英雄級（Heroic）スペシャリスト</strong>: 新レア度。極めて希少で名声コストが高く、セーブデータごとに各1体のみ所持可。効果は強力。 <ul><li>（例）「パルディウス」— チーズによる人口+2・健康+1、羊牧場のチーズ産出+1t/12サイクル、羊牧場の必要労働力を軽減。</li></ul></li><li><strong>フォトモード</strong>: フリーカメラ・時間帯選択・レンズ効果。</li><li><strong>メモ機能</strong>: ゲーム内メモ。</li><li>円形闘技場の9段階バフシステム。</li><li>住民の反復クエスト。</li><li>パンの消費量+50%。供給時の人口ボーナスが+2→+3に増加し、小麦粉の生産時間が30秒/tから20秒/tに短縮。</li><li>火災・疫病の建物への影響を強化。</li></ul><p>2026年8月20日追加。</p>',21)])])}const b=l(a,[["render",d]]);export{c as __pageData,b as default};
